policies.schema:
// Neutral fixture fragment used by the contract vectors: a notes system that no production server implements. It has a flat
// type that can be granted and checked early (Notebook), a child with a parent (Note) and a path-shaped type whose scopes
// are prefixes of its path (Folder).

namespace Notes {
  entity Notebook {
    name: String,
    labels: Set<String>,
    scopes: Set<ResourceScope>,
  };
  entity Note in [Notebook] {
    title: String,
    pinned?: Bool,
    notebook: Notebook,
    scopes: Set<ResourceScope>,
  };
  entity Folder {
    path: String,
    classification?: Set<String>,
    scopes: Set<ResourceScope>,
  };

  action "read", "update", "delete", "admin" appliesTo {
    principal: [User],
    resource: [Notebook, Note, Folder],
    context: RequestContext,
  };
}

files.text:
// A service account sees everything in its system, so the rights of the user are the only limit left. A folder outside the
// user's grant is forbidden unless the credential is a user credential, which the system itself limits. Fail-closed: a
// missing or unknown credential type is treated like the service account (CC-136, CC-164).

@id("notes-service-account-folder-outside-scope")
forbid (principal, action, resource is Notes::Folder)
when {
  !(principal in resource.scopes) &&
  !(context has credentialType && ["user-oauth", "user-secret", "token-exchange"].contains(context.credentialType))
};

@id("notes-forbid-restricted-notebook")
forbid (principal, action, resource is Notes::Notebook)
when { resource.labels.contains("restricted") };

@id("notes-forbid-restricted-note")
forbid (principal, action, resource is Notes::Note)
when { resource.notebook.labels.contains("restricted") };

@id("notes-forbid-restricted-folder")
forbid (principal, action, resource is Notes::Folder)
when { resource has classification && resource.classification.contains("restricted") };

@id("notes-read")
permit (
  principal in UserGroup::"mcp-notes-read",
  action == Notes::Action::"read",
  resource
)
when { resource is Notes::Notebook || resource is Notes::Note || resource is Notes::Folder };

// Changes only inside granted scopes; a note carries the scope of its notebook, a folder the scope of every prefix of its path.

@id("notes-update-in-scope")
permit (
  principal in UserGroup::"mcp-notes-write",
  action == Notes::Action::"update",
  resource
)
when { principal in resource.scopes };

@id("notes-delete-in-scope")
permit (
  principal in UserGroup::"mcp-notes-destructive",
  action == Notes::Action::"delete",
  resource is Notes::Note
)
when { principal in resource.scopes };

// Changes only inside granted scopes; a note carries the scope of its notebook, a folder the scope of every prefix of its path.

@id("notes-update-in-scope")
permit (
  principal in UserGroup::"mcp-notes-write",
  action == Notes::Action::"update",
  resource
)
when { principal in resource.scopes };

@id("notes-delete-in-scope")
permit (
  principal in UserGroup::"mcp-notes-destructive",
  action == Notes::Action::"delete",
  resource is Notes::Note
)
when { principal in resource.scopes };
